toad_implementation.code_blueprint:
canvas {
  size: 800px 1000px;
  fill: #FAFAFA;
  font-family: "Montserrat, sans-serif";
}

>cardWhite = #FAFAFA;
>slate = #2D3748;
>orange = #ED8936;
>foldGray = #CBD5E1;

rect #sideB_Flipped {
  at: top left of canvas;
  size: 800px 490px;
  fill: #FFFFFF;
  rotation: 180;
}

text #sideB_Title {
  at: center of #sideB_Flipped offset 0px -40px;
  content: "RESERVIERT";
  font-size: 36px;
  font-weight: 800;
  color: >orange;
  rotation: 180;
}

text #sideB_Sub {
  at: below #sideB_Title offset 16px;
  content: "TABLE RESERVED FOR GUEST OF HONOR";
  font-size: 13px;
  font-weight: 600;
  color: >slate;
  rotation: 180;
}

rect #foldLine {
  at: center of canvas;
  size: 800px 2px;
  fill: >foldGray;
}

rect #sideA_Normal {
  at: bottom left of canvas;
  size: 800px 490px;
  fill: #FFFFFF;
}

text #sideA_Title {
  at: center of #sideA_Normal offset 0px -40px;
  content: "RESERVIERT";
  font-size: 36px;
  font-weight: 800;
  color: >orange;
}

text #sideA_Sub {
  at: below #sideA_Title offset 16px;
  content: "TABLE RESERVED FOR GUEST OF HONOR";
  font-size: 13px;
  font-weight: 600;
  color: >slate;
}
